1	/**
2	 * Types for Qwen Code transcript parsing.
3	 *
4	 * Qwen Code transcripts are JSONL files with ChatRecords linked by
5	 * uuid/parentUuid but emitted in chronological order. Messages use a
6	 * Gemini-style `{role, parts: [...]}` envelope, and parts can be one of:
7	 *   - `{text, thought?}` — model/user text (thought=true marks internal reasoning)
8	 *   - `{functionCall: {id, name, args}}` — model requesting a tool call
9	 *   - `{functionResponse: {id, name, response}}` — result returned to the model
10	 *
11	 * Tool results additionally appear as standalone records with
12	 * `type: 'tool_result'` that carry a `toolCallResult` block with
13	 * `{callId, status, resultDisplay}` — matched to the assistant's
14	 * functionCall by call id.
15	 *
16	 * Location: ~/.qwen/projects/<project-id>/chats/<sessionId>.jsonl
17	 */
18	
19	/**
20	 * A single ChatRecord in the Qwen Code JSONL transcript.
21	 */
22	export interface ChatRecord {
23	  uuid: string;
24	  parentUuid: string | null;
25	  sessionId: string;
26	  timestamp: string;
27	  type: 'user' | 'assistant' | 'system' | 'tool_result';
28	  /** Gemini-style message envelope; `system` records may have no parts. */
29	  message?: GeminiMessage | string;
30	  model?: string;
31	  usageMetadata?: UsageMetadata;
32	  /** Present on `tool_result` records. Matched to an assistant functionCall by callId. */
33	  toolCallResult?: ToolCallResult;
34	  cwd?: string;
35	  gitBranch?: string;
36	  version?: string;
37	  contextWindowSize?: number;
38	  subtype?: string;
39	  systemPayload?: unknown;
40	}
41	
42	/**
43	 * Gemini-style message envelope used by Qwen Code.
44	 */
45	export interface GeminiMessage {
46	  role: string;
47	  parts: GeminiPart[];
48	}
49	
50	/**
51	 * One piece of a Gemini message. Real transcripts contain four shapes:
52	 * text with optional `thought` flag, function calls, and function responses.
53	 */
54	export type GeminiPart = TextPart | FunctionCallPart | FunctionResponsePart;
55	
56	export interface TextPart {
57	  text: string;
58	  /** Internal chain-of-thought reasoning. Exclude from user-facing content. */
59	  thought?: boolean;
60	}
61	
62	export interface FunctionCallPart {
63	  functionCall: FunctionCall;
64	}
65	
66	export interface FunctionResponsePart {
67	  functionResponse: FunctionResponse;
68	}
69	
70	export interface FunctionCall {
71	  id: string;
72	  name: string;
73	  args?: Record<string, unknown>;
74	}
75	
76	export interface FunctionResponse {
77	  id: string;
78	  name: string;
79	  response?: Record<string, unknown>;
80	}
81	
82	/**
83	 * Token usage metadata on assistant records. Qwen uses Gemini-style keys
84	 * (promptTokenCount / candidatesTokenCount / totalTokenCount), with
85	 * OpenAI-style fallbacks occasionally appearing.
86	 */
87	export interface UsageMetadata {
88	  promptTokenCount?: number;
89	  candidatesTokenCount?: number;
90	  totalTokenCount?: number;
91	  thoughtsTokenCount?: number;
92	  cachedContentTokenCount?: number;
93	  input_tokens?: number;
94	  output_tokens?: number;
95	}
96	
97	/**
98	 * Tool result payload on `tool_result` records.
99	 *
100	 * Status values observed in real transcripts:
101	 *   - `success` — tool completed normally
102	 *   - `cancelled` — user declined a permission prompt
103	 *   - (other values are treated as failures defensively)
104	 */
105	export interface ToolCallResult {
106	  callId: string;
107	  status: string;
108	  /** Can be a plain string or a structured object (e.g. file diff for write_file). */
109	  resultDisplay?: string | Record<string, unknown>;
110	}
111	
112	/**
113	 * Stop hook input received via stdin.
114	 */
115	export interface StopHookInput {
116	  session_id: string;
117	  transcript_path: string | null;
118	  cwd: string;
119	  hook_event_name: string;
120	  timestamp: string;
121	}
122	
123	/**
124	 * OpenAI chat-format tool call, attached to assistant messages in LLM span
125	 * inputs so the MLflow Chat view renders tool invocations correctly.
126	 */
127	export interface ToolCall {
128	  id: string;
129	  type: 'function';
130	  function: {
131	    name: string;
132	    arguments: string;
133	  };
134	}
135	
136	/**
137	 * OpenAI chat-format message used in LLM span inputs.
138	 */
139	export interface ChatMessage {
140	  role: 'user' | 'assistant' | 'system' | 'tool';
141	  content: string | null;
142	  tool_calls?: ToolCall[];
143	  tool_call_id?: string;
144	}
