135	 */
136	export function withSpan<T>(
137	  callback: (span: LiveSpan) => T | Promise<T>,
138	  options?: Omit<SpanOptions, 'parent'>,
139	): T | Promise<T> {
140	  if (isTracingEnabledInContext() === false) {
141	    return callback(new NoOpSpan());
