 * Types for Claude Code transcript parsing.
 *
 * Claude Code writes conversation transcripts as JSONL files where each line
 * is a `TranscriptEntry`. Assistant and user messages use the Anthropic
 * message envelope (`{role, content}`) where `content` is either a plain
 * string or a list of content blocks (`text`, `tool_use`, `tool_result`).
 *
 * Sub-agents (spawned via the `Task` tool) surface in two shapes:
 *   - Inline `progress` entries whose `parentToolUseID` points back at the
 *     `Task` tool_use, carrying the sub-agent's own messages in `data.message`.
 *   - Separate transcript files at
 *     `<transcript_dir>/<transcript_basename>/subagents/agent-<agentId>.jsonl`,
 *     referenced by `toolUseResult.agentId` on the Task tool result.
 */

/**
 * A single content block inside an Anthropic message. The `type` field is the
 * discriminator; the remaining fields are populated depending on the type.
 */
export interface ContentBlock {
  type: string;
  /** Present on `text` blocks. */
  text?: string;
  /** Present on `tool_use` blocks. */
  id?: string;
  name?: string;
  input?: Record<string, any>;
  /** Present on `tool_result` blocks. */
  tool_use_id?: string;
  content?: string | ContentBlock[] | any;
  is_error?: boolean;
  [key: string]: any;
}

/**
 * Token usage reported by the Anthropic API on assistant messages.
 */
export interface Usage {
  input_tokens?: number;
  output_tokens?: number;
  cache_creation_input_tokens?: number;
  cache_read_input_tokens?: number;
  [key: string]: any;
}

/**
 * The Anthropic message envelope carried on `user`/`assistant` entries.
 */
export interface Message {
  role: string;
  content: string | ContentBlock[];
  model?: string;
  usage?: Usage;
  [key: string]: any;
}

/**
 * Structured tool result metadata attached to a tool result user entry.
 */
export interface ToolUseResult {
  status?: string;
  agentId?: string;
  totalDurationMs?: number;
  success?: boolean;
  commandName?: string;
  [key: string]: any;
}

/**
 * Payload of an inline sub-agent `progress` entry.
 */
export interface ProgressData {
  type: string;
  agentId: string;
  prompt: string;
  /** A nested transcript entry emitted by the sub-agent. */
  message: TranscriptEntry;
  [key: string]: any;
}

/**
 * A single entry in a Claude Code JSONL transcript.
 */
export interface TranscriptEntry {
  type: string;
  message?: Message;
  timestamp?: string | number;
  sessionId?: string;
  agentId?: string;
  version?: string;
  permissionMode?: string;
  isCompactSummary?: boolean;
  toolUseResult?: ToolUseResult;

