  parentToolUseID?: string;
  toolUseID?: string;
  data?: ProgressData;

  /** Present on `queue-operation` entries. */
  operation?: string;
  content?: string;

  [key: string]: any;
}

/**
 * Stop hook input received via stdin from Claude Code.
 */
export interface StopHookInput {
  session_id: string;
  transcript_path: string | null;
  cwd: string;
  hook_event_name: string;
  [key: string]: any;
}
