 * Transcript parsing utilities for Claude Code JSONL files.
 *
 * Claude Code writes conversation transcripts to
 * `~/.claude/projects/<project-id>/<sessionId>.jsonl`. Each non-empty line is
 * a JSON `TranscriptEntry`, emitted in chronological order.
 */

import { readFileSync } from 'node:fs';
import type { ContentBlock, TranscriptEntry } from './types.js';

export const NANOSECONDS_PER_MS = 1e6;
export const NANOSECONDS_PER_S = 1e9;

const CONTENT_TYPE_TEXT = 'text';
const CONTENT_TYPE_TOOL_RESULT = 'tool_result';
const SKILL_INJECTION_PREFIX = 'Base directory:';

function isRecord(value: unknown): value is Record<string, any> {
  return typeof value === 'object' && value !== null;
}

/** Read and parse a Claude Code JSONL transcript file, one entry per line. */
export function readTranscript(filePath: string): TranscriptEntry[] {
  const content = readFileSync(filePath, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as TranscriptEntry);
}

/**
 * Convert a timestamp to nanoseconds since the Unix epoch.
 *
 * ISO date strings are parsed via `Date`. Numeric values are treated as
 * nanoseconds if `>= 1e13`, milliseconds if `>= 1e10`, or Unix seconds
 * otherwise. Returns null for null/undefined/empty-string inputs and for
 * strings that are not valid dates.
 */
export function parseTimestampToNs(ts: string | number | null | undefined): number | null {
  if (ts === null || ts === undefined || ts === '') {
    return null;
  }

  if (typeof ts === 'number') {
    if (ts >= 1e13) {
      return Math.floor(ts);
    }
    if (ts >= 1e10) {
      return Math.floor(ts * NANOSECONDS_PER_MS);
    }
    return Math.floor(ts * NANOSECONDS_PER_S);
  }

  const ms = new Date(ts).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from an Anthropic message content value. A string is
 * returned unchanged; an array joins the `text` of all `text`-type blocks
 * with `\n`. An empty array yields an empty string.
 */
export function extractTextContent(
  content: string | Array<{ type: string; text?: string; [key: string]: any }>,
): string {
  if (typeof content === 'string') {
    return content;
  }
  if (Array.isArray(content)) {
    return content
      .filter((part) => isRecord(part) && part.type === CONTENT_TYPE_TEXT)
      .map((part) => part.text ?? '')
      .join('\n');
  }
  return String(content);
}

/**
 * Find the index of the last "real" user message in the transcript.
 *
 * Skips tool result messages (user entries whose content is an array of
 * `tool_result` blocks), compact summary entries, and skill injection
 * messages (user text content starting with `Base directory:`). Returns null
 * for an empty transcript or when no real user message exists.
 */
export function findLastUserMessageIndex(entries: TranscriptEntry[]): number | null {
  for (let i = entries.length - 1; i >= 0; i--) {
    const entry = entries[i];
    if (entry.type !== 'user') {
      continue;
    }
    if (entry.isCompactSummary === true) {
      continue;
    }

    const content = entry.message?.content;

    // Skip tool result messages (content is an array of tool_result blocks).
    if (
      Array.isArray(content) &&
      content.length > 0 &&
      isRecord(content[0]) &&
      content[0].type === CONTENT_TYPE_TOOL_RESULT
    ) {
      continue;
    }

    // Skip skill injection messages.
    const text = extractTextContent(content ?? []);
    if (text.startsWith(SKILL_INJECTION_PREFIX)) {
      continue;
    }

    return i;
  }
  return null;
}

/**
 * Search from `startIndex` onward for the last assistant message that has
 * text content, returning that extracted text or null.
 */
export function findFinalAssistantResponse(
  entries: TranscriptEntry[],
  startIndex: number,
): string | null {
  let finalResponse: string | null = null;

  for (let i = startIndex; i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'assistant') {
      continue;
    }
    const content = entry.message?.content ?? [];
    const text = extractTextContent(content);
    if (text.trim()) {
      finalResponse = text;
    }
  }

  return finalResponse;
}

/**
 * Split an assistant message's content into concatenated text and the list of
 * `tool_use` blocks it contains.
 */
export function extractContentAndTools(content: string | ContentBlock[]): {
  text: string;
  toolUses: ContentBlock[];
} {
  let text = '';
  const toolUses: ContentBlock[] = [];

  if (Array.isArray(content)) {
    for (const part of content) {
      if (!isRecord(part)) {
        continue;
      }
      if (part.type === CONTENT_TYPE_TEXT) {
        text += part.text ?? '';
      } else if (part.type === 'tool_use') {
        toolUses.push(part as ContentBlock);
      }
    }
  }

  return { text, toolUses };
}

/**
 * Information about a tool result, keyed by the tool_use id it corresponds to.
 */
export interface ToolResultInfo {
  content: string | ContentBlock[] | any;
  isError: boolean;
  agentId?: string;
}

/**
 * Build a map from tool_use id to its result, scanning user entries that
 * follow the assistant entry at `startIdx`.
 */
export function findToolResults(
  entries: TranscriptEntry[],
  startIdx: number,
): Map<string, ToolResultInfo> {
  const results = new Map<string, ToolResultInfo>();

  for (let i = startIdx + 1; i < entries.length; i++) {
    const entry = entries[i];
    if (entry.type !== 'user') {
      continue;
    }

    const content = entry.message?.content;
    if (!Array.isArray(content)) {
      continue;
    }

    for (const part of content) {
      if (isRecord(part) && part.type === CONTENT_TYPE_TOOL_RESULT) {
        const toolUseId = part.tool_use_id;
        if (toolUseId) {
          results.set(toolUseId, {
            content: part.content ?? '',
            isError: part.is_error === true,
            agentId: entry.toolUseResult?.agentId,
          });
        }
      }
    }
  }

  return results;
}

/**
 * Get the timestamp (ns) of the next entry after `currentIdx` that has one.
 */
export function getNextTimestampNs(
  entries: TranscriptEntry[],
  currentIdx: number,
): number | null {
  for (let i = currentIdx + 1; i < entries.length; i++) {
    const ts = entries[i].timestamp;
    if (ts !== undefined && ts !== null && ts !== '') {
      return parseTimestampToNs(ts);
    }
  }
  return null;
}

/**
 * Reconstruct the Anthropic-format message history leading up to the assistant
 * entry at `currentIdx`. Walks backward, stopping at the previous
 * text-bearing assistant entry (the previous LLM boundary), and includes
 * queued steer messages (`queue-operation` with operation `enqueue`).
 */
export function getInputMessages(
  entries: TranscriptEntry[],
  currentIdx: number,
): Array<Record<string, any>> {
  const messages: Array<Record<string, any>> = [];

