      let hasText = false;
      if (typeof content === 'string') {
        hasText = content.trim().length > 0;
      } else if (Array.isArray(content)) {
        hasText = content.some((p) => isRecord(p) && p.type === CONTENT_TYPE_TEXT);
      }
