 JSONL transcript and emits an MLflow trace shaped as:\n *\n *   AGENT claude_code_conversation\n *   ├─ LLM  llm                    (one per text-bearing assistant turn)\n *   ├─ TOOL tool_<name>            (one per tool_use)\n *   └─ TOOL tool_Task\n *      └─ AGENT subagent_<type>    (nested sub-agent activity)\n *         ├─ LLM  llm\n *         └─ TOOL tool_<name>\n *\n * Sub-agents (spawned via the `Task` tool) are reconstructed from either\n * inline `progress` entries (referenced by `parentToolUseID`) or from a\n * separate transcript file referenced by the tool result's `agentId`.\n */\n\nimport { basename, dirname, extname, join } from 'node:path';\nimport { existsSync } from 'node:fs';\n\nimport {\n  startSpan,\n  flushTraces,\n  InMemoryTraceManager,\n  SpanStatusCode,\n  SpanType,\n  SpanAttributeKey,\n  TraceMetadataKey,\n  TokenUsageKey,\n  type LiveSpan,\n} from '@mlflow/core';\n\nimport type { ContentBlock, TranscriptEntry, Usage } from './types.js';\nimport {\n  NANOSECONDS_PER_MS,\n  NANOSECONDS_PER_S,\n  extractContentAndTools,\n  extractTextContent,\n  findFinalAssistantResponse,\n  findLastUserMessageIndex,\n  findToolResults,\n  getInputMessages,\n  getNextTimestampNs,\n  parseTimestampToNs,\n  readTranscript,\n  type ToolResultInfo,\n} from './transcript.js';\n\nconst MESSAGE_FORMAT_ANTHROPIC = 'anthropic';\nconst TOOL_NAME_TASK = 'Task';\nconst DEFAULT_TOOL_DURATION_NS = 1000 * NANOSECONDS_PER_MS;\n\nconst METADATA_KEY_WORKING_DIRECTORY = 'mlflow.trace.working_directory';\nconst METADATA_KEY_PERMISSION_MODE = 'mlflow.trace.permission_mode';\nconst METADATA_KEY_CLAUDE_CODE_VERSION = 'mlflow.claude_code_version';\n\n/**\n * Shared context threaded through the recursive span builders so that\n * sub-agent lookups (inline progress entries and separate transcript files)\n * can be resolved relative to the top-level transcript.\n */\ninterface BuildContext {\n  /** The full top-level transcript, used to resolve inline progress entries. */\n  allEntries: TranscriptEntry[];\n  /** Directory containing the transcript file. */\n  transcriptDir: string;\n  /** Transcript filename without extension (the sub-agent directory name). */\n  transcriptBase: string;\n}\n\n/**\n * Read a Claude Code transcript file and convert it into an MLflow trace.\n *\n * Missing files, empty transcripts, and transcripts with no real user message\n * are handled gracefully by creating no spans.\n */\nexport async function processTranscript(filePath: string, sessionId: string): Promise<void> {\n  let transcript: TranscriptEntry[];\n  try {\n    transcript = readTranscript(filePath);\n  } catch {\n    return;\n  }\n\n  if (transcript.length === 0) {\n    return;\n  }\n\n  const lastUserIdx = findLastUserMessageIndex(transcript);\n  if (lastUserIdx == null) {\n    return;\n  }\n\n  const lastUserEntry = transcript[lastUserIdx];\n  const lastUserContent = lastUserEntry.message?.content ?? '';\n  const userPromptText = extractTextContent(lastUserContent);\n\n  const convStartNs = parseTimestampToNs(lastUserEntry.timestamp);\n\n  const rootSpan = startSpan({\n    name: 'claude_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: { prompt: userPromptText },\n    ...(convStartNs != null ? { startTimeNs: convStartNs } : {}),\n  });\n\n  const ctx: BuildContext = {\n    allEntries: transcript,\n    transcriptDir: dirname(filePath),\n    transcriptBase: basename(filePath, extname(filePath)),\n  };\n\n  createLlmAndToolSpans(rootSpan, transcript, lastUserIdx + 1, ctx);\n\n  const finalResponse = findFinalAssistantResponse(transcript, lastUserIdx + 1);\n\n  // Compute the conversation end time from the last entry with a timestamp,\n  // falling back to a fixed duration when timing is missing or inconsistent.\n  const lastEntry = transcript[transcript.length - 1];\n  let convEndNs = parseTimestampToNs(lastEntry.timestamp);\n  if (convEndNs == null || (convStartNs != null && convEndNs <= convStartNs)) {\n    convEndNs = (convStartNs ?? 0) + 10 * NANOSECONDS_PER_S;\n  }\n\n  setTraceMetadata(rootSpan, transcript, sessionId, userPromptText, finalResponse);\n\n  rootSpan.end({\n    outputs:\n      finalResponse != null\n        ? { status: 'completed', response: finalResponse }\n        : { status: 'completed' },\n    ...(convEndNs != null ? { endTimeNs: convEndNs } : {}),\n  });\n\n  await flushTraces();\n}\n\n/**\n * Set trace-level previews and metadata. Hook-based integrations have no\n * active OTel span context, so we update the in-memory trace directly.\n */\nfunction setTraceMetadata(\n  rootSpan: LiveSpan,\n  transcript: TranscriptEntry[],\n  sessionId: string,\n  userPromptText: string,\n  finalResponse: string | null,\n): void {\n  const traceId = rootSpan.traceId;\n  if (!traceId) {\n    return;\n  }\n\n  const trace = InMemoryTraceManager.getInstance().getTrace(traceId);\n  if (!trace) {\n    return;\n  }\n\n  if (userPromptText) {\n    trace.info.requestPreview = userPromptText;\n  }\n  if (finalResponse) {\n    trace.info.responsePreview = finalResponse;\n  }\n\n  const metadata: Record<string, string> = {\n    [TraceMetadataKey.TRACE_SESSION]: sessionId,\n    [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',\n    [METADATA_KEY_WORKING_DIRECTORY]: process.cwd(),\n  };\n\n  const permissionMode = transcript.find(\n    (entry) => entry.type === 'user' && entry.permissionMode,\n  )?.permissionMode;\n  if (permissionMode) {\n    metadata[METADATA_KEY_PERMISSION_MODE] = permissionMode;\n  }\n\n  const version = transcript.find((entry) => entry.version)?.version;\n  if (version) {\n    metadata[METADATA_KEY_CLAUDE_CODE_VERSION] = version;\n  }\n\n  trace.info.traceMetadata = {\n    ...trace.info.traceMetadata,\n    ...metadata,\n  };\n}\n\n/**\n * Walk the entries from `startIdx` onward, creating an LLM span for each\n * text-only assistant turn and a TOOL span for each tool_use. Task tool_uses\n * additionally get a nested sub-agent AGENT span.\n */\nfunction createLlmAndToolSpans(\n  parentSpan: LiveSpan,\n  entries: TranscriptEntry[],\n  startIdx: number,\n  ctx: BuildContext,\n): void {\n  for (let i = startIdx; i < entries.length; i++) {\n    const entry = entries[i];\n    if (entry.type !== 'assistant') {\n      continue;\n    }\n\n    const timestampNs = parseTimestampToNs(entry.timestamp);\n    const nextTimestampNs = getNextTimestampNs(entries, i);\n    const durationNs =\n      timestampNs != null\n        ? nextTimestampNs != null\n          ? nextTimestampNs - timestampNs\n          : DEFAULT_TOOL_DURATION_NS\n        : null;\n\n    const msg = entry.message;\n    const content = msg?.content ?? [];\n    const usage = msg?.usage;\n    const model = msg?.model ?? 'unknown';\n\n    const { text, toolUses } = extractContentAndTools(content);\n\n    // An LLM span is emitted only for pure-text assistant turns; turns that\n    // issue tool calls are represented by their TOOL spans.\n    if (text.trim() && toolUses.length === 0) {\n      const messages = getInputMessages(entries, i);\n      const llmSpan = startSpan({\n        name: 'llm',\n        parent: parentSpan,\n        spanType: SpanType.LLM,\n        ...(timestampNs != null ? { startTimeNs: timestampNs } : {}),\n        inputs: { model, messages },\n        attributes: {\n          model,\n          [SpanAttributeKey.MESSAGE_FORMAT]: MESSAGE_FORMAT_ANTHROPIC,\n        },\n      });\n\n      setTokenUsage(llmSpan, usage);\n\n      llmSpan.end({\n        outputs: { type: 'message', role: 'assistant', content },\n        ...(timestampNs != null && durationNs != null\n          ? { endTimeNs: timestampNs + durationNs }\n          : {}),\n      });\n    }\n\n    if (toolUses.length > 0) {\n      const toolResults = findToolResults(entries, i);\n      const toolDurationNs = durationNs != null ? Math.floor(durationNs / toolUses.length) : null;\n\n      toolUses.forEach((toolUse, idx) => {\n        createToolSpan(parentSpan, toolUse, toolResults, timestampNs, toolDurationNs, idx, ctx);\n      });\n    }\n  }\n}\n\n/**\n * Create a single TOOL span, wiring up its result output, error status, and\n * (for `Task` tools) any nested sub-agent hierarchy.\n */\nfunction createToolSpan(\n  parentSpan: LiveSpan,\n  toolUse: ContentBlock,\n  toolResults: Map<string, ToolResultInfo>,\n  turnTimestampNs: number | null,\n  toolDurationNs: number | null,\n  idx: number,\n  ctx: BuildContext,\n): void {\n  const toolName = toolUse.name ?? 'unknown';\n  const toolId = toolUse.id ?? '';\n  const result = toolResults.get(toolId);\n\n  const toolStartNs =\n    turnTimestampNs != null && toolDurationNs != null\n      ? turnTimestampNs + idx * toolDurationNs\n      : null;\n\n  const toolSpan = startSpan({\n    name: `tool_${toolName}`,\n    parent: parentSpan,\n    spanType: SpanType.TOOL,\n    ...(toolStartNs != null ? { startTimeNs: toolStartNs } : {}),\n    inputs: toolUse.input ?? {},\n    attributes: { tool_name: toolName, tool_id: toolId },\n  });\n\n  // A rejected tool use surfaces as an error result; record it as an\n  // exception so it is visible in the trace UI.\n  if (result?.isError) {\n    const message = toErrorMessage(result.content);\n    toolSpan.recordException(new Error(message));\n    toolSpan.setStatus(SpanStatusCode.ERROR, message);\n  }\n\n  // Reconstruct sub-agent activity for Task tool uses.\n  if (toolName === TOOL_NAME_TASK) {\n    buildSubAgentSpan(toolSpan, toolUse, result, toolStartNs, toolDurationNs, ctx);\n  }\n\n  toolSpan.end({\n    outputs: { result: result?.content ?? 'No result found' },\n    ...(toolStartNs != null && toolDurationNs != null\n      ? { endTimeNs: toolStartNs + toolDurationNs }\n      : {}),\n  });\n}\n\n/**\n * Build a nested `subagent_<type>` AGENT span (with its own LLM/TOOL children)\n * under a `tool_Task` span, from inline progress entries or a separate file.\n */\nfunction buildSubAgentSpan(\n  toolSpan: LiveSpan,\n  toolUse: ContentBlock,\n  result: ToolResultInfo | undefined,\n  startNs: number | null,\n  durationNs: number | null,\n  ctx: BuildContext,\n): void {\n  const subagentType = (toolUse.input?.subagent_type as string | undefined) ?? 'unknown';\n  const toolId = toolUse.id ?? '';\n\n  // Prefer inline progress entries referencing this Task tool_use.\n  const progressEntries = ctx.allEntries.filter(\n    (entry) =>\n      entry.type === 'progress' && entry.parentToolUseID === toolId && entry.data?.message != null,\n  );\n\n  let subEntries: TranscriptEntry[] | null = null;\n\n  if (progressEntries.length > 0) {\n    subEntries = [];\n    for (const entry of progressEntries) {\n      const message = entry.data?.message;\n      if (!message) {\n        continue;\n      }\n      // Inherit the progress entry's timestamp when the nested message lacks one.\n      subEntries.push(\n        message.timestamp != null ? message : { ...message, timestamp: entry.timestamp },\n      );\n    }\n  } else if (result?.agentId) {\n    const subPath = join(\n      ctx.transcriptDir,\n      ctx.transcriptBase,\n      'subagents',\n      `agent-${result.agentId}.jsonl`,\n    );\n    if (existsSync(subPath)) {\n      try {\n        subEntries = readTranscript(subPath);\n      } catch {\n        subEntries = null;\n      }\n    }\n  }\n\n  if (!subEntries || subEntries.length === 0) {\n    return;\n  }\n\n  const promptText = extractTextContent((toolUse.input?.prompt as string | undefined) ?? '');\n  const subagentSpan = startSpan({\n    name: `subagent_${subagentType}`,\n    parent: toolSpan,\n    spanType: SpanType.AGENT,\n    ...(startNs != null ? { startTimeNs: startNs } : {}),\n    inputs: { prompt: promptText, subagent_type: subagentType },\n    attributes: { subagent_type: subagentType },\n  });\n\n  createLlmAndToolSpans(subagentSpan, subEntries, 0, ctx);\n\n  const subResponse = findFinalAssistantResponse(subEntries, 0);\n  subagentSpan.end({\n    outputs:\n      subResponse != null\n        ? { status: 'completed', response: subResponse }\n        : { status: 'completed' },\n    ...(startNs != null && durationNs != null ? { endTimeNs: startNs + durationNs } : {}),\n  });\n}\n\n/**\n * Attach standardized token usage to a span. `input_tokens` includes\n * `cache_creation_input_tokens` (comparable cost) but excludes\n * `cache_read_input_tokens` (much cheaper, would inflate estimates).\n */\nfunction setTokenUsage(span: LiveSpan, usage: Usage | undefined): void {\n  if (!usage || Object.keys(usage).length === 0) {\n    return;\n  }\n\n  const inputTokens = (usage.input_tokens ?? 0) + (usage.cache_creation_input_tokens ?? 0);\n  const outputTokens = usage.output_tokens ?? 0;\n\n  span.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n    [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n    [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n    [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n  });\n}\n\n/** Render a tool result content value into an error message string. */\nfunction toErrorMessage(content: unknown): string {\n  if (typeof content === 'string' && content.trim()) {\n    return content;\n  }\n  if (Array.isArray(content)) {\n    const rendered = extractTextContent(content);\n    if (rendered.trim()) {\n      return rendered;\n    }\n  }\n  return \"The user doesn't want to proceed with this tool use.\";\n}\n"],"version":3}
