H,IAAI,CAAC,wCAAwC,EAAE,KAAK,IAAI,EAAE;IACxD,MAAM,IAAA,2BAAiB,EAAC,yBAAyB,EAAE,GAAG,CAAC,CAAC;IACxD,MAAM,CAAC,KAAK,EAAE,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,CAAC,CAAC,CAAC;IAC/B,MAAM,CAAC,kBAAW,CAAC,CAAC,GAAG,CAAC,gBAAgB,EAAE,CAAC;IAE3C,MAAM,KAAK,GAAG,UAAU,CAAC,aAAa,EAAE,EAAE,CAAC,CAAC;IAC5C,MAAM,IAAA,2BAAiB,EAAC,KAAK,EAAE,GAAG,CAAC,CAAC;IACpC,MAAM,CAAC,KAAK,EAAE,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,CAAC,CAAC,CAAC;IAE/B,MAAM,MAAM,GAAG,UAAU,CAAC,cAAc,EAAE;QACxC,EAAE,IAAI,EAAE,MAAM,EAAE,OAAO,EAAE,EAAE,IAAI,EAAE,MAAM,EAAE,OAAO,EAAE,CAAC,EAAE,IAAI,EAAE,aAAa,EAAE,WAAW,EAAE,GAAG,EAAE,OAAO,EAAE,GAAG,EAAE,CAAC,EAAE,EAAE,SAAS,EAAE,0BAA0B,EAAE;KACvJ,CAAC,CAAC;IACH,MAAM,IAAA,2BAAiB,EAAC,MAAM,EAAE,GAAG,CAAC,CAAC;IACrC,MAAM,CAAC,KAAK,EAAE,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,CAAC,CAAC,CAAC;AACjC,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/claude-code/tests/scratch.test.ts"],"sourcesContent":["import { resolve } from 'path';\nimport { writeFileSync, mkdirSync } from 'fs';\nimport { tmpdir } from 'os';\n\nlet spanCounter = 0;\nconst mockSpans: Record<string, any> = {};\nconst mockTraceInfo: {\n  requestPreview?: string;\n  responsePreview?: string;\n  traceMetadata: Record<string, string>;\n} = { traceMetadata: {} };\n\njest.mock('@mlflow/core', () => ({\n  init: jest.fn(),\n  startSpan: jest.fn((options: any) => {\n    const id = `span-${++spanCounter}`;\n    const parentId = options.parent ? options.parent.spanId : null;\n    const span: any = {\n      name: options.name,\n      traceId: 'mock-trace-id',\n      spanId: id,\n      parentId,\n      spanType: options.spanType ?? 'UNKNOWN',\n      inputs: options.inputs ?? {},\n      outputs: {},\n      attributes: { ...(options.attributes ?? {}) },\n      startTimeNs: options.startTimeNs ?? null,\n      endTimeNs: null,\n      statusCode: null,\n      statusMessage: null,\n      exceptions: [] as Error[],\n      setAttribute: jest.fn((k: string, v: any) => {\n        span.attributes[k] = v;\n      }),\n      setStatus: jest.fn((c: string, m?: string) => {\n        span.statusCode = c;\n        span.statusMessage = m ?? null;\n      }),\n      recordException: jest.fn((e: Error) => {\n        span.exceptions.push(e);\n      }),\n      end: jest.fn((opts?: any) => {\n        if (opts?.outputs != null) span.outputs = opts.outputs;\n        if (opts?.endTimeNs != null) span.endTimeNs = opts.endTimeNs;\n      }),\n    };\n    mockSpans[id] = span;\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanStatusCode: { OK: 'OK', ERROR: 'STATUS_CODE_ERROR', UNSET: 'UNSET' },\n  SpanType: { LLM: 'LLM', AGENT: 'AGENT', TOOL: 'TOOL', UNKNOWN: 'UNKNOWN' },\n  SpanAttributeKey: { TOKEN_USAGE: 'mlflow.chat.tokenUsage', MESSAGE_FORMAT: 'mlflow.message.format' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  TokenUsageKey: { INPUT_TOKENS: 'input_tokens', OUTPUT_TOKENS: 'output_tokens', TOTAL_TOKENS: 'total_tokens' },\n  InMemoryTraceManager: {\n    getInstance: jest.fn(() => ({ getTrace: jest.fn(() => ({ info: mockTraceInfo })) })),\n  },\n}));\n\nimport { processTranscript } from '../src/tracing';\nimport { flushTraces } from '@mlflow/core';\n\nconst spans = () => Object.values(mockSpans);\nconst byType = (t: string) => spans().filter((s: any) => s.spanType === t);\nconst root = () => spans().find((s: any) => s.parentId == null);\n\nfunction writeJsonl(name: string, entries: any[]): string {\n  const dir = resolve(tmpdir(), `cc-${Date.now()}-${Math.floor(Math.random() * 1e6)}`);\n  mkdirSync(dir, { recursive: true });\n  const p = resolve(dir, name);\n  writeFileSync(p, entries.map((e) => JSON.stringify(e)).join('\\n') + '\\n');\n  return p;\n}\n\nbeforeEach(() => {\n  spanCounter = 0;\n  Object.keys(mockSpans).forEach((k) => delete mockSpans[k]);\n  mockTraceInfo.traceMetadata = {};\n  mockTraceInfo.requestPreview = undefined;\n  mockTraceInfo.responsePreview = undefined;\n  jest.clearAllMocks();\n});\n\nconst DUMMY = [\n  { type: 'user', message: { role: 'user', content: 'What is 2 + 2?' }, timestamp: '2025-01-15T10:00:00.000Z', sessionId: 's', permissionMode: 'default' },\n  { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Let me calculate that for you.' }] }, timestamp: '2025-01-15T10:00:01.000Z' },\n  { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'tool_123', name: 'Bash', input: { command: 'echo $((2 + 2))' } }] }, timestamp: '2025-01-15T10:00:02.000Z' },\n  { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'tool_123', content: '4' }] }, timestamp: '2025-01-15T10:00:03.000Z' },\n  { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'The answer is 4.' }] }, timestamp: '2025-01-15T10:00:04.000Z' },\n];\n\ntest('basic: root AGENT, 2 LLM, 1 TOOL, metadata, previews', async () => {\n  const p = writeJsonl('t.jsonl', DUMMY);\n  await processTranscript(p, 'sess-1');\n  const r = root();\n  expect(r.name).toBe('claude_code_conversation');\n  expect(r.spanType).toBe('AGENT');\n  expect(r.inputs).toEqual({ prompt: 'What is 2 + 2?' });\n  expect(r.outputs).toEqual({ status: 'completed', response: 'The answer is 4.' });\n  expect(byType('LLM').length).toBe(2);\n  expect(byType('TOOL').length).toBe(1);\n  const tool = byType('TOOL')[0];\n  expect(tool.name).toBe('tool_Bash');\n  expect(tool.inputs).toEqual({ command: 'echo $((2 + 2))' });\n  expect(tool.attributes.tool_name).toBe('Bash');\n  expect(tool.attributes.tool_id).toBe('tool_123');\n  expect(tool.outputs).toEqual({ result: '4' });\n  const llm = byType('LLM')[0];\n  expect(llm.attributes['mlflow.message.format']).toBe('anthropic');\n  expect(llm.outputs.type).toBe('message');\n  expect(llm.outputs.role).toBe('assistant');\n  expect(Array.isArray(llm.outputs.content)).toBe(true);\n  expect(llm.inputs.messages.some((m: any) => m.role === 'user')).toBe(true);\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('sess-1');\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.working_directory']).toBe(process.cwd());\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.permission_mode']).toBe('default');\n  expect(mockTraceInfo.requestPreview).toBe('What is 2 + 2?');\n  expect(mockTraceInfo.responsePreview).toBe('The answer is 4.');\n  expect(flushTraces).toHaveBeenCalled();\n});\n\ntest('token usage with cache tokens', async () => {\n  const p = writeJsonl('u.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'Hi' }, timestamp: '2025-01-15T10:00:00.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Hello' }], model: 'claude', usage: { input_tokens: 36, cache_creation_input_tokens: 23554, cache_read_input_tokens: 139035, output_tokens: 3344 } }, timestamp: '2025-01-15T10:00:01.000Z' },\n  ]);\n  await processTranscript(p, 'sess-2');\n  const llm = byType('LLM')[0];\n  expect(llm.attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 23590, output_tokens: 3344, total_tokens: 26934 });\n});\n\ntest('steer / enqueue message included in second LLM inputs; other ops ignored', async () => {\n  const p = writeJsonl('s.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'Tell me about Python.' }, timestamp: '2025-01-15T10:00:00.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Python is a language.' }] }, timestamp: '2025-01-15T10:00:01.000Z' },\n    { type: 'queue-operation', operation: 'enqueue', content: 'also tell me about Java', timestamp: '2025-01-15T10:00:02.000Z' },\n    { type: 'queue-operation', operation: 'remove', timestamp: '2025-01-15T10:00:03.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Java too.' }] }, timestamp: '2025-01-15T10:00:04.000Z' },\n  ]);\n  await processTranscript(p, 'sess-3');\n  const llms = byType('LLM');\n  expect(llms.length).toBe(2);\n  const steer = llms[1].inputs.messages.filter((m: any) => m.content === 'also tell me about Java');\n  expect(steer.length).toBe(1);\n  expect(steer[0].role).toBe('user');\n});\n\ntest('version metadata + skill injection skipped', async () => {\n  const p = writeJsonl('v.jsonl', [\n    { type: 'user', version: '2.1.34', message: { role: 'user', content: 'Do the thing.' }, timestamp: '2025-01-15T10:00:00.000Z' },\n    { type: 'assistant', version: '2.1.34', message: { role: 'assistant', content: [{ type: 'tool_use', id: 't1', name: 'Skill', input: { skill: 'x' } }] }, timestamp: '2025-01-15T10:00:01.000Z' },\n    { type: 'user', toolUseResult: { commandName: 'x' }, message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 't1', content: 'launch' }] }, timestamp: '2025-01-15T10:00:02.000Z' },\n    { type: 'user', message: { role: 'user', content: [{ type: 'text', text: 'Base directory: /x\\n# Skill' }] }, timestamp: '2025-01-15T10:00:03.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'Done.' }] }, timestamp: '2025-01-15T10:00:04.000Z' },\n  ]);\n  await processTranscript(p, 'sess-4');\n  expect(root().inputs).toEqual({ prompt: 'Do the thing.' });\n  expect(mockTraceInfo.traceMetadata['mlflow.claude_code_version']).toBe('2.1.34');\n});\n\ntest('error tool records exception', async () => {\n  const p = writeJsonl('e.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'rm stuff' }, timestamp: '2025-01-15T10:00:00.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 'te', name: 'Bash', input: { command: 'rm -rf /' } }] }, timestamp: '2025-01-15T10:00:01.000Z' },\n    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'te', is_error: true, content: \"The user doesn't want to proceed with this tool use.\" }] }, timestamp: '2025-01-15T10:00:02.000Z' },\n  ]);\n  await processTranscript(p, 'sess-5');\n  const tool = byType('TOOL')[0];\n  expect(tool.recordException).toHaveBeenCalled();\n  expect(tool.exceptions[0].message).toContain(\"doesn't want to proceed\");\n});\n\ntest('parallel Task tools each get its own result; inline subagent nested', async () => {\n  const p = writeJsonl('task.jsonl', [\n    { type: 'user', message: { role: 'user', content: 'spawn agents' }, timestamp: '2025-01-15T10:00:00.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [\n      { type: 'tool_use', id: 'task1', name: 'Task', input: { subagent_type: 'explorer', prompt: 'explore' } },\n      { type: 'tool_use', id: 'task2', name: 'Task', input: { subagent_type: 'writer', prompt: 'write' } },\n    ] }, timestamp: '2025-01-15T10:00:01.000Z' },\n    { type: 'progress', parentToolUseID: 'task1', toolUseID: 'task1', timestamp: '2025-01-15T10:00:01.500Z', data: { type: 'agent', agentId: 'a1', prompt: 'explore', message: { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'explored' }] }, timestamp: '2025-01-15T10:00:01.600Z' } } },\n    { type: 'user', message: { role: 'user', content: [\n      { type: 'tool_result', tool_use_id: 'task1', content: 'result-1' },\n      { type: 'tool_result', tool_use_id: 'task2', content: 'result-2' },\n    ] }, timestamp: '2025-01-15T10:00:02.000Z' },\n    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'text', text: 'all done' }] }, timestamp: '2025-01-15T10:00:03.000Z' },\n  ]);\n  await processTranscript(p, 'sess-6');\n  const tasks = spans().filter((s: any) => s.name === 'tool_Task');\n  expect(tasks.length).toBe(2);\n  const t1 = tasks.find((s: any) => s.attributes.tool_id === 'task1');\n  const t2 = tasks.find((s: any) => s.attributes.tool_id === 'task2');\n  expect(t1.outputs).toEqual({ result: 'result-1' });\n  expect(t2.outputs).toEqual({ result: 'result-2' });\n  const sub = spans().find((s: any) => s.name === 'subagent_explorer');\n  expect(sub).toBeDefined();\n  expect(sub.spanTy